import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { 
  Box, 
  Typography, 
  Breadcrumbs, 
  Link as MuiLink, 
  Button, 
  TextField, 
  Avatar, 
  Divider, 
  IconButton,
  Paper,
  Grid,
  Container,
  Chip,
  Tabs,
  Tab,
  Card,
  CardContent,
  CardMedia,
  Stack
} from '@mui/material';
import { 
  ThumbUp as ThumbUpIcon, 
  ChatBubbleOutline as CommentIcon,
  Share as ShareIcon,
  BookmarkBorder as BookmarkIcon,
  MoreVert as MoreVertIcon,
  Reply as ReplyIcon,
  ArrowForward as ArrowForwardIcon
} from '@mui/icons-material';
import { formatDistanceToNow } from 'date-fns';
import { styled } from '@mui/material/styles';
import api from '../utils/api';

// Styled components
const ArticleImage = styled('img')({
  width: '100%',
  maxHeight: '500px',
  objectFit: 'cover',
  borderRadius: '8px',
  margin: '20px 0'
});

const CommentCard = styled(Paper)(({ theme }) => ({
  padding: theme.spacing(2),
  marginBottom: theme.spacing(2),
  backgroundColor: theme.palette.background.paper,
}));

const ArticleDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const [article, setArticle] = useState(null);
  const [comments, setComments] = useState([]);
  const [commentText, setCommentText] = useState('');
  const [relatedArticles, setRelatedArticles] = useState([]);
  const [activeTab, setActiveTab] = useState('mostRelevant');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchArticle = async () => {
      try {
        setLoading(true);
        // Fetch article details
        const articleRes = await api.get(`/news/${id}`);
        setArticle(articleRes.data);

        // Fetch comments
        const commentsRes = await api.get(`/news/${id}/comments`);
        setComments(commentsRes.data);

        // Fetch related articles
        const relatedRes = await api.get(`/news/related/${articleRes.data.category}`);
        setRelatedArticles(relatedRes.data);
      } catch (error) {
        console.error('Error fetching article:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchArticle();
    // Scroll to comments if needed
    if (location.state?.scrollToComments) {
      const timer = setTimeout(() => {
        const commentsSection = document.getElementById('comments-section');
        if (commentsSection) {
          commentsSection.scrollIntoView({ behavior: 'smooth' });
          // Clear the state to prevent scrolling again on re-renders
          window.history.replaceState({ ...location.state, scrollToComments: false }, '');
        }
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [id, location.state]);

  const handleCommentSubmit = async (e) => {
    e.preventDefault();
    if (!commentText.trim()) return;

    try {
      const response = await api.post(`/news/${id}/comments`, { text: commentText });
      setComments([response.data, ...comments]);
      setCommentText('');
    } catch (error) {
      console.error('Error posting comment:', error);
    }
  };

  const handleLikeComment = async (commentId) => {
    try {
      await api.post(`/comments/${commentId}/like`);
      setComments(comments.map(comment => 
        comment._id === commentId 
          ? { ...comment, likes: comment.likes + 1, isLiked: true } 
          : comment
      ));
    } catch (error) {
      console.error('Error liking comment:', error);
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (!article) {
    return <div>Article not found</div>;
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Grid container spacing={4}>
        {/* Main Content */}
        <Grid item xs={12} md={8}>
          {/* Breadcrumb */}
          <Breadcrumbs aria-label="breadcrumb" sx={{ mb: 3 }}>
            <MuiLink color="inherit" href="/">
              Home
            </MuiLink>
            <MuiLink color="inherit" href={`/category/${article.category}`}>
              {article.category}
            </MuiLink>
            <Typography color="text.primary">{article.title}</Typography>
          </Breadcrumbs>

          {/* Article Header */}
          <Typography variant="h4" component="h1" gutterBottom>
            {article.title}
          </Typography>
          
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 3, color: 'text.secondary' }}>
            <Typography variant="body2">
              {article.source} • {formatDistanceToNow(new Date(article.publishedAt), { addSuffix: true })}
            </Typography>
            <Box sx={{ ml: 'auto', display: 'flex', gap: 1 }}>
              <IconButton size="small">
                <ShareIcon fontSize="small" />
              </IconButton>
              <IconButton size="small">
                <BookmarkIcon fontSize="small" />
              </IconButton>
            </Box>
          </Box>

          {/* Article Image */}
          <ArticleImage 
            src={article.imageUrl} 
            alt={article.title} 
            onError={(e) => {
              e.target.onerror = null;
              e.target.src = '/placeholder-news.jpg';
            }}
          />

          {/* Article Content */}
          <Box sx={{ mb: 4 }}>
            <Typography variant="body1" paragraph>
              {article.summary}
            </Typography>
            <Button 
              variant="contained" 
              color="primary" 
              href={article.url} 
              target="_blank"
              rel="noopener noreferrer"
              sx={{ mt: 2 }}
            >
              Read Original Article
            </Button>
          </Box>

          {/* Comments Section */}
          <Box id="comments-section" sx={{ mt: 6, pt: 2 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
              <Typography variant="h6">
                {comments.length} Comments
              </Typography>
              <Box>
                <Tabs 
                  value={activeTab} 
                  onChange={(e, newValue) => setActiveTab(newValue)}
                  sx={{ minHeight: 'auto' }}
                >
                  <Tab value="mostRelevant" label="Most Relevant" sx={{ p: 1, minHeight: 'auto' }} />
                  <Tab value="newest" label="Newest" sx={{ p: 1, minHeight: 'auto' }} />
                </Tabs>
              </Box>
            </Box>

            {/* Comment Form */}
            <Paper sx={{ p: 2, mb: 4 }}>
              <Typography variant="subtitle2" gutterBottom>
                Share your view on this news
              </Typography>
              <Box component="form" onSubmit={handleCommentSubmit}>
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  variant="outlined"
                  placeholder="Write your opinion..."
                  value={commentText}
                  onChange={(e) => setCommentText(e.target.value)}
                  sx={{ mb: 2 }}
                />
                <Button 
                  type="submit" 
                  variant="contained" 
                  color="primary"
                  disabled={!commentText.trim()}
                >
                  Post Opinion
                </Button>
              </Box>
            </Paper>

            {/* Comments List */}
            <Box>
              {comments.map((comment) => (
                <CommentCard key={comment._id} elevation={0}>
                  <Box sx={{ display: 'flex', gap: 2 }}>
                    <Avatar src={comment.user?.avatar} alt={comment.user?.name} />
                    <Box sx={{ flex: 1 }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                        <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
                          {comment.user?.name || 'Anonymous'}
                        </Typography>
                        <Typography variant="caption" color="text.secondary" sx={{ ml: 1 }}>
                          {formatDistanceToNow(new Date(comment.createdAt), { addSuffix: true })}
                        </Typography>
                      </Box>
                      <Typography variant="body2" sx={{ mb: 1 }}>
                        {comment.text}
                      </Typography>
                      <Box sx={{ display: 'flex', gap: 2, mt: 1 }}>
                        <Button 
                          size="small" 
                          startIcon={<ThumbUpIcon fontSize="small" />}
                          onClick={() => handleLikeComment(comment._id)}
                          color={comment.isLiked ? 'primary' : 'inherit'}
                        >
                          {comment.likes || 0}
                        </Button>
                        <Button 
                          size="small" 
                          startIcon={<ReplyIcon fontSize="small" />}
                        >
                          Reply
                        </Button>
                      </Box>
                    </Box>
                  </Box>
                </CommentCard>
              ))}
            </Box>
          </Box>
        </Grid>

        {/* Sidebar */}
        <Grid item xs={12} md={4}>
          <Box sx={{ position: 'sticky', top: 20 }}>
            {/* Read More Section */}
            <Paper sx={{ p: 2, mb: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h6">Read more</Typography>
                <MuiLink href="#" color="primary" sx={{ display: 'flex', alignItems: 'center' }}>
                  View all <ArrowForwardIcon fontSize="small" sx={{ ml: 0.5 }} />
                </MuiLink>
              </Box>
              
              <Tabs 
                value={0} 
                variant="fullWidth"
                sx={{ mb: 2 }}
              >
                <Tab label="Most Relevant" />
                <Tab label="Most Liked" />
              </Tabs>

              <Box sx={{ mb: 3 }}>
                <Chip 
                  label="Womments 22" 
                  color="primary" 
                  variant="outlined"
                  sx={{ mb: 2 }}
                />
              </Box>

              {/* Related Articles */}
              <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 2 }}>
                Related Articles
              </Typography>
              
              <Stack spacing={2}>
                {relatedArticles.slice(0, 3).map((item) => (
                  <Card key={item._id} elevation={0} sx={{ display: 'flex', gap: 2 }}>
                    <Box sx={{ width: 100, height: 80, flexShrink: 0 }}>
                      <CardMedia
                        component="img"
                        image={item.imageUrl}
                        alt={item.title}
                        sx={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 1 }}
                      />
                    </Box>
                    <CardContent sx={{ p: 1, flex: 1 }}>
                      <Chip 
                        label={item.category} 
                        size="small" 
                        sx={{ mb: 0.5, height: 20, fontSize: '0.65rem' }} 
                      />
                      <Typography variant="body2" sx={{ fontWeight: 500, mb: 0.5 }}>
                        {item.title.length > 60 ? `${item.title.substring(0, 60)}...` : item.title}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {item.source} • {formatDistanceToNow(new Date(item.publishedAt), { addSuffix: true })}
                      </Typography>
                    </CardContent>
                  </Card>
                ))}
              </Stack>

              <Button 
                fullWidth 
                variant="outlined" 
                sx={{ mt: 2 }}
              >
                VIEW ALL
              </Button>
            </Paper>

            {/* Related News Section */}
            <Paper sx={{ p: 2 }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 2 }}>
                Related News
              </Typography>
              
              <Stack spacing={2}>
                {relatedArticles.slice(3, 6).map((item) => (
                  <Box key={`related-${item._id}`} sx={{ display: 'flex', gap: 2, pb: 2, borderBottom: '1px solid', borderColor: 'divider' }}>
                    <Box sx={{ width: 80, height: 60, flexShrink: 0 }}>
                      <CardMedia
                        component="img"
                        image={item.imageUrl}
                        alt={item.title}
                        sx={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 1 }}
                      />
                    </Box>
                    <Box sx={{ flex: 1 }}>
                      <Chip 
                        label={item.category} 
                        size="small" 
                        sx={{ mb: 0.5, height: 20, fontSize: '0.6rem' }} 
                      />
                      <Typography variant="body2" sx={{ fontWeight: 500, lineHeight: 1.2 }}>
                        {item.title.length > 60 ? `${item.title.substring(0, 60)}...` : item.title}
                      </Typography>
                    </Box>
                  </Box>
                ))}
              </Stack>
            </Paper>
          </Box>
        </Grid>
      </Grid>
    </Container>
  );
};

export default ArticleDetail;
